window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-632aab5f7d9c2a8a"]={"versions": [{"id": "FIG-632aab5f7d9c2a8a", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Write Counter“ innerhalb der AUTOSAR E2E-Bibliotheksfunktion <code>E2E_P04Forward()</code>. Das Diagramm beschreibt die Zustands- und Pufferbehandlung für Profil 4 (E2E Profile 4 Forwarding) bei Weiterleitung von Nutzdaten über Gateways oder Brücken.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Kontext:</strong> <code>E2E_P04Forward()</code>\n</li><li><strong>Zustands- und Konfigurationsstrukturen:</strong>\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: 16-Bit-Zähler (<code>uint16</code>) des E2E-Status.\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurierter Maximalwert für Zählersprünge.\n</li><li><code>ForwardStatus</code>: Status der Weiterleitungsprüfung (mögliche Werte: <code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code>).\n</li><li><code>Data</code>: Nutzdaten-Byte-Array.\n</li><li><code>Offset</code>: Konfigurierter Offset im Datenpuffer.\n</li></ul>\n</li><li><strong>Verzweigungsknoten (Decisions) und Merge-Knoten:</strong> Kaskadierte Fallunterscheidungen zur Anpassung von <code>State-&gt;Counter</code>.\n</li><li><strong>Kommentar-Notiz:</strong> Definiert den Datentyp von <code>State-&gt;Counter</code> als <code>uint16</code> mit Überlaufverhalten (nach <code>0xFFFF</code> folgt <code>0</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Übergang vom Startknoten in die kaskadierte Auswertung des <code>ForwardStatus</code>.\n</li><li><strong>Fallprüfung 1:</strong> <code>if ForwardStatus == E2E_P_REPEATED</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter--</code>).\n</li><li><code>[FALSE]</code>: Weiterleitung zur nächsten Bedingung.\n</li></ul>\n</li><li><strong>Fallprüfung 2:</strong> <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Anpassung des Zählers via <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>.\n</li><li><code>else</code>: Keine Zähleranpassung, direkter Sprung zum Zusammenführungsknoten.\n</li></ul>\n</li><li><strong>Zusammenführung (Merge):</strong> Alle Pfade laufen an einem gemeinsamen Merge-Knoten zusammen.\n</li><li><strong>Serialisierung:</strong> Ausführung der Aktion <code>Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order</code>.\n</li><li><strong>Ende:</strong> Erreichen des Aktivitätsendknotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Algorithmus zur Zählerberechnung und -eintragung für E2E Profile 4 Forwarding (<code>[PRS_E2E_00617]</code>). Entwickler müssen sicherstellen, dass die Zählerarithmetik modular im 16-Bit-Zahlenraum (<code>uint16</code>) arbeitet (Überlauf von <code>0xFFFF</code> nach <code>0x0000</code>, Unterlauf bei Dekrement entsprechend). Zudem ist die 2-Byte-Ablage im Datenstrom zwingend in Big-Endian-Byte-Reihenfolge an Position <code>Data[Offset+2...Offset+3]</code> umzusetzen.</p>"}, {"id": "FIG-2eb3af35c03c234d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Write Counter“ innerhalb der AUTOSAR E2E-Bibliotheksfunktion <code>E2E_P04Forward()</code>. Das Diagramm beschreibt die Zustands- und Pufferbehandlung für Profil 4 (E2E Profile 4 Forwarding) bei Weiterleitung von Nutzdaten über Gateways oder Brücken.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Kontext:</strong> <code>E2E_P04Forward()</code>\n</li><li><strong>Zustands- und Konfigurationsstrukturen:</strong>\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: 16-Bit-Zähler (<code>uint16</code>) des E2E-Status.\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurierter Maximalwert für Zählersprünge.\n</li><li><code>ForwardStatus</code>: Status der Weiterleitungsprüfung (mögliche Werte: <code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code>).\n</li><li><code>Data</code>: Nutzdaten-Byte-Array.\n</li><li><code>Offset</code>: Konfigurierter Offset im Datenpuffer.\n</li></ul>\n</li><li><strong>Verzweigungsknoten (Decisions) und Merge-Knoten:</strong> Kaskadierte Fallunterscheidungen zur Anpassung von <code>State-&gt;Counter</code>.\n</li><li><strong>Kommentar-Notiz:</strong> Definiert den Datentyp von <code>State-&gt;Counter</code> als <code>uint16</code> mit Überlaufverhalten (nach <code>0xFFFF</code> folgt <code>0</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Übergang vom Startknoten in die kaskadierte Auswertung des <code>ForwardStatus</code>.\n</li><li><strong>Fallprüfung 1:</strong> <code>if ForwardStatus == E2E_P_REPEATED</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter--</code>).\n</li><li><code>[FALSE]</code>: Weiterleitung zur nächsten Bedingung.\n</li></ul>\n</li><li><strong>Fallprüfung 2:</strong> <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Anpassung des Zählers via <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>.\n</li><li><code>else</code>: Keine Zähleranpassung, direkter Sprung zum Zusammenführungsknoten.\n</li></ul>\n</li><li><strong>Zusammenführung (Merge):</strong> Alle Pfade laufen an einem gemeinsamen Merge-Knoten zusammen.\n</li><li><strong>Serialisierung:</strong> Ausführung der Aktion <code>Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order</code>.\n</li><li><strong>Ende:</strong> Erreichen des Aktivitätsendknotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Algorithmus zur Zählerberechnung und -eintragung für E2E Profile 4 Forwarding (<code>[PRS_E2E_00617]</code>). Entwickler müssen sicherstellen, dass die Zählerarithmetik modular im 16-Bit-Zahlenraum (<code>uint16</code>) arbeitet (Überlauf von <code>0xFFFF</code> nach <code>0x0000</code>, Unterlauf bei Dekrement entsprechend). Zudem ist die 2-Byte-Ablage im Datenstrom zwingend in Big-Endian-Byte-Reihenfolge an Position <code>Data[Offset+2...Offset+3]</code> umzusetzen.</p>"}], "trans": [{"from": "FIG-632aab5f7d9c2a8a", "to": "FIG-2eb3af35c03c234d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
